GUIDE = ("كل درس يُبنى وفق: وضعية انطلاقية تصاغ في سياق الدرس وتكون مشوقة ومثيرة لدافعية المتعلم؛ وضعيات البناء (عرض السند والعناصر)؛ "
         "وضعيات الإرساء والإدماج الجزئي والتقويم (وضعيات بسيطة). دروس القرآن: تلاوة السورة وفق رواية ورش عن نافع بمحاكاة مقرئ مع تطبيق أحكام التجويد المدروسة، "
         "وتوجيه المتعلمين إلى حفظ السورة ومتابعة ذلك؛ مهمة للتنفيذ خارج القسم (كتابة السورة ومعاني مفرداتها أو البحث عن سبب النزول) يراقبها المعلم في المراقبة المستمرة. "
         "معايير التقويم: اكتساب معارف، توظيف معارف، اكتساب قيم و/أو اتخاذ مواقف؛ ومعايير الكفاءة: الوجاهة، الاستعمال السليم لأدوات المادة، الانسجام، الإتقان. "
         "نهاية كل فصل: إدماج كلي (خلال الأسبوع ما قبل الاختبار) ثم الاختبار.")
TERM_NAMES = {1: "الفصل الأول", 2: "الفصل الثاني", 3: "الفصل الثالث"}


def build_level(n):
    out = []
    for t in (1, 2, 3):
        lessons = [{"title": f"{i:02d}. {title}", "domain": dom, "hint": f"العناصر: {el}"} for i, (dom, title, el) in enumerate(L[n][t], start=1)]
        lessons.append({"title": f"الإدماج الكلي ({TERM_NAMES[t]})", "domain": L[n][t][0][0],
                        "hint": "وضعية إدماجية لتقويم المستوى المستهدف من الكفاءة الشاملة (تتعلق بكل أو معظم مقاطع الفصل)، خلال الأسبوع ما قبل الاختبار."})
        doms = sorted({d for d, _, _ in L[n][t]}, key=DOMAINS.index)
        out.append({
            "title": TERM_NAMES[t],
            "official": {
                "source": SRC.format(n=n),
                "levels": {"المستوى المستهدف من الكفاءة الشاملة": TERM_LEVEL[(n, t)], "الكفاءة الشاملة": GLOBAL[n]},
                "resources": {"الكفاءات الختامية للميادين": " | ".join(f"{d}: {TERMINAL[d]}" for d in doms),
                              "دروس الفصل": "؛ ".join(f"{title} ({dom})" for dom, title, _ in L[n][t])},
                "situation": "تصاغ الوضعية الانطلاقية في سياق الدرس وتكون مشوقة ومثيرة لدافعية المتعلم للتعلم.",
                "tasks": ["وضعيات البناء: عرض السند والعناصر", "وضعيات الإرساء والإدماج الجزئي والتقويم: صياغة وضعيات بسيطة لإرساء التعلمات وللإدماج الجزئي والتقويم"],
                "criteria": ["اكتساب معارف: يذكر/يعرّف/يشرح العناصر المدروسة", "توظيف معارف: يستشهد ويستدل ويتلو تلاوة سليمة بتطبيق الأحكام",
                             "اكتساب قيم و/أو اتخاذ مواقف: يتمثل القيم المستخلصة في سلوكه"],
            },
            "lessons": lessons,
        })
    return out


if __name__ == "__main__":
    path = Path(__file__).parent / "curriculum.json"
    data = json.loads(path.read_text(encoding="utf-8"))
    s = next(x for x in data["subjects"] if x["id"] == "islamic")
    s["domains"] = DOMAINS
    for n in (1, 2, 3, 4):
        s["levels"][str(n)] = build_level(n)
        s.setdefault("guidelines", {})[str(n)] = GUIDE
        s.setdefault("verified", {})[str(n)] = SRC.format(n=n)
    path.write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding="utf-8")
    print({n: [len(L[n][t]) for t in (1, 2, 3)] for n in L})
